def is_same_tree(p: list, q: list) -> bool:
    def walk(a, b) -> bool:
        if a is None or b is None:
            return a is b
        return a.value == b.value and walk(a.left, b.left) and walk(a.right, b.right)

    return walk(_build(p), _build(q))

